// Turn the plugin's blog summary into a short list of problems worth a person's attention.
// Thresholds are deliberately simple; change them in this node.
const s = $input.first().json;
const pct = v => parseInt(String(v), 10);
const checks = [
  [pct(s.with_any_external_source) < 80, `Only ${s.with_any_external_source} of posts cite an outside source.`],
  [pct(s.with_3plus_statistics) < 30, `Only ${s.with_3plus_statistics} of posts have 3 or more statistics.`],
  [pct(s.with_faq_section) < 20, `Only ${s.with_faq_section} of posts have an FAQ section.`],
  [pct(s.updated_in_last_180_days) < 50, `Only ${s.updated_in_last_180_days} of posts were updated in the last 180 days.`],
];
const problems = checks.filter(([bad]) => bad).map(([, msg]) => msg);
return [{ json: { site: $('Config').first().json.site_url, posts: s.posts, ok: problems.length === 0, problems } }];
